draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw leaf
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2 - 60, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 + 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 70);
  ctx.lineTo(W/2 - 100, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 100);
  ctx.lineTo(W/2 - 120, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 100);
  ctx.lineTo(W/2 - 80, H/2 + 120);
  ctx.stroke();

  // draw eating action
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 150);
  ctx.lineTo(W/2 - 50 + 20 * Math.sin(t), H/2 + 100);
  ctx.stroke();

  ctx.restore();
}
